class Solution:
    def sumOfLows(self, prices: List[int]) -> int:
        n = len(prices)
        total = 0
        for i in range(n):
            l = i
            while l > 0 and prices[l - 1] >= prices[i]:
                l -= 1
            r = i
            while r < n - 1 and prices[r + 1] > prices[i]:
                r += 1
            total += prices[i] * (i - l + 1) * (r - i + 1)
        return total % (10**9 + 7)

