class Solution:
    def sumOfLows(self, prices: List[int]) -> int:
        n = len(prices)
        left = [0] * n
        stack = []
        for i in range(n):
            while stack and prices[stack[-1]] >= prices[i]:
                stack.pop()
            left[i] = i - (stack[-1] if stack else -1)
            stack.append(i)
        stack, total = [], 0
        for i in range(n - 1, -1, -1):
            while stack and prices[stack[-1]] > prices[i]:
                stack.pop()
            right = (stack[-1] if stack else n) - i
            total += prices[i] * left[i] * right
            stack.append(i)
        return total % (10**9 + 7)

