class Solution {
    public int sumOfLows(int[] prices) {
        int n = prices.length;
        int[] left = new int[n], stack = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && prices[stack[top - 1]] >= prices[i]) top--;
            left[i] = i - (top > 0 ? stack[top - 1] : -1);
            stack[top++] = i;
        }
        long total = 0;
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && prices[stack[top - 1]] > prices[i]) top--;
            int right = (top > 0 ? stack[top - 1] : n) - i;
            total += (long) prices[i] * left[i] * right;
            stack[top++] = i;
        }
        return (int) (total % 1_000_000_007);
    }
}

